import{_ as a,c as e,o as s,af as t}from"./chunks/framework.BKeRpnBD.js";const h=JSON.parse('{"title":"雜卦傳","description":"周易尚氏學 - 雜卦傳","frontmatter":{"title":"雜卦傳","description":"周易尚氏學 - 雜卦傳"},"headers":[],"relativePath":"classics/shangshi/074.md","filePath":"classics/shangshi/074.md"}'),r={name:"classics/shangshi/074.md"};function i(n,p,c,_,o,l){return s(),e("div",null,[...p[0]||(p[0]=[t('<h1 id="雜卦傳" tabindex="-1">雜卦傳 <a class="header-anchor" href="#雜卦傳" aria-label="Permalink to “雜卦傳”">​</a></h1><p>十翼以雜卦終。與山六十四卦以未濟終義同也。蓋六十四卦卦序皆文王所定。其起訖皆有深義不可動搖。然易道以不窮為義。六十四卦至既濟而六爻定。定則窮矣。故殿以未濟。使之復通。六十四卦。上經始天地。下經始夫婦。此不易者也。故雜卦仍之。而以井困居上經之末。以損益為樞紐。以未濟夬居下經之末。以否泰為樞紐。損益否泰。後先互易。明文王之意。先天道。後人事。孔子之意。先人事後天道也。先人事。並取其不窮。困而不失其亨。故以為上經之殿。聽天道。則事之濟不濟命也。剛健果決。自強不息。終焉以赴之耳。故以未濟夬終。仍窮變通久之義也。謂之為雜者。言雜柔（左未）各卦。使上下經互易。不與文王卦序同。非孔子不敢有此改作。亦非孔子無此神化之筆也。彼七十二賢固不敢創制如斯也。以上所言。雜卦殿十翼之義也。至其所言。必錯綜對舉者何也。以見卦象正則如此。反則如彼也。正象說卦舉其端。說卦所未言者。可類推也。至覆象則無言者。然如大過九五枯楊。人尚知為反巽。獨正覆象相雜。如蒙匪我求童蒙。童蒙求我。初筮告。再三讀。讀則不告。則以二至上。正反震也。如左傳以謙為敗言。則以謙下艮。與震相反也。如困曰有言不信。則以三至上。正覆兌也。如震曰婚媾有言。則以二至上正覆震相背也。如中孚曰鶴鳴子和。則以二至五正反震相對。如相應也。鳴鶴在陰者。則以二至五正反民。正則為山陽。反則為山陰也。又六三雲。或鼓或罷。或泣或歌。則以二至五正反艮震。震則或鼓或歌。艮則或泣或罷也。如此之類。經內甚多。除焦氏易林外。二千年說者無不誤。夫子蓋預知之。故於最後之雜卦申其義。</p><p>乾剛坤柔。比樂師憂。</p><p>比五雖坎。然當位居尊。故樂。師二人淵。故憂。</p><p>臨觀之義。或與或求。</p><p>臨二陽撫臨萬民。有施惠之意。震往。故曰與。反之為觀。則萬民仰五。有乞求之意。故曰求。艮為求也。</p><p>屯見而不失其居。蒙雜而著。</p><p>屯二陽皆當位。故不失其居。蒙二陽皆失位。故曰雜。物相雜則文生。故曰著。</p><p>震起也。艮止也。損益盛衰之始也。</p><p>震動故起。反則止矣。泰損上一陽以益上。故損為衰之始。再三損則成否否移上一陽以益下。故益為盛之始。再三益則成泰。</p><p>大畜時也。無妄災也。</p><p>王引之雲。古時與待通。恐天災至。畜以待飢。人本坤靈圖。無妄互艮。艮為火。故災。焦京皆以無妄為大旱卦。自艮火象失傳。虞氏即不知其義。</p><p>萃聚而升不來也。謙輕而豫怠也。</p><p>陽上升。故不來。廉不自滿。故輕。豫自足。故怠。怠虞作怡。按怠怡皆從心。本一字。故古常通用。史記始皇本紀。視聽不怠。劉歆烈女贊。言行不怠。注並作怡。怡則自足。與謙輕反。</p><p>噬嗑食也。賁無色也。兌見而巽伏也。</p><p>頤中有物。故曰食。火在山下。與明夷同。故曰元色。兌陰在上故曰見。巽陰在下故曰伏。故巽亦為盜賊。為寇戎。為豕。與坎同象。</p><p>隨元故也。蠱則飭也。剝爛也。復反也。晉晝也。明夷誅也。</p><p>志在隨時。不執其故。廣韻。飭整備也。蠱則飭者。亂極思治也。爛自姤始。至剝而極。復則陽反。曰在上故晝。誅傷也。明傷則夜矣。</p><p>井通而因相遇也。</p><p>並養而不窮故通。困剛掩。陽陷陰中。不通。自乾坤至此仍三十卦。合上經數。自鹹恆至夬。仍三十四卦。合下經數。</p><p>鹹速也。恆久也。渙離也。節止也。</p><p>感則無遠近。無弗屆。故事莫速於感。反之為恆。則不速而久。渙者散也。故曰離。反之為節。則合而不離。故曰止。</p><p>解緩也。蹇難也。睽外也。家人內也。</p><p>緩則和矣。和則易矣。反之則難。睽離女在上卦。故曰外。反之在內。故曰內也。</p><p>否泰反其類也。</p><p>陰陽交為類。否陰交陽。泰陽交陰。故曰反。</p><p>大壯則止。遁則退也。大有眾也。同人親也。</p><p>止則不退。反之則退。眾則不親。反之則親。</p><p>革去故也。鼎取新也。小過過也。中孚信也。</p><p>革更改舊有。故曰去故。鼎亨飪待熟。故曰取新。過失也。失刖不信。反之則信。</p><p>豐多故也。親寡旅也。離上而坎下也。</p><p>多與寡相反。上與下相反。豐雷電皆至故多。旅互巽為寡。艮為鰥。故親寡。火炎上。水潤下。</p><p>小畜寡也。履不處也。需不進也。訟不親也。</p><p>小畜巽為寡。履者行也。故不處。需險在前。故不進。訟天水違行。故不親。寡則獨處。反之則不處矣。不親則異行。與需之不行。亦正相反。</p><p>大過顛也。姤遇也。柔遇剛也。</p><p>顛隕也。下巽隕落。頂滅澤中。故顛。姤坤遇乾。乾剛坤柔。</p><p>漸女歸待男行也。頤養正也。既濟定也。</p><p>漸陰皆居陽後。故待男行。頤求口食。得養之正。既濟山六爻當位而止其所。故曰定。</p><p>歸妹女之終也。未濟男之窮也。</p><p>女終夫家。故以嫁為終。既濟三陽皆比陰。內剛外柔。與泰理同。故不窮。未濟三陽皆居陰前。內柔外剛。與否理同。故窮。程子謂三陽不當位故窮。豈知三女亦不當位。豈獨三男。然而不窮者。以三女皆承陽也。程子謂來之多年。不得其義。後得之於成都箍桶者。蓋託辭也。</p><p>夬決也。剛決柔也。君子道長。小人道憂也。</p><p>沈善登雲。雜卦以乾剛坤柔始。以夬剛決柔。還復為乾終。是舉全易渾成一乾。按此說最得夬卦居終之義。自大過以下。不兩卦反對。宋儒頗疑為錯簡。然曰女之終。男之窮。上下對文。似非錯簡。惟義仍反對。大過死。反之則得養。姤柔遇剛。反之則剛決柔。漸女有待而行。反之則不待而嫁矣。既濟定。窮則不定。雖不對舉。而義仍反對。虞翻謂大過死。大過下姤。故次以後。上夾故以決終。亦可參考。</p>',42)])])}const f=a(r,[["render",i]]);export{h as __pageData,f as default};
